using Dhole.Content.Domain.ContentItems.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.ContentItems;internal sealed class ContentTaxonomyConfiguration:IEntityTypeConfiguration<ContentTaxonomy>{public void Configure(EntityTypeBuilder<ContentTaxonomy>b){b.ToTable("content_taxonomies");b.HasKey(x=>new{x.ContentId,x.TaxonomyTermId});b.HasOne(x=>x.TaxonomyTerm).WithMany().HasForeignKey(x=>x.TaxonomyTermId).OnDelete(DeleteBehavior.Cascade);}}
